// ── Simple linear regression via gradient descent ─────────────
// Goal: learn y = w*x + b from data points

const data = [
  { x: 1, y: 2.1 }, { x: 2, y: 3.9 }, { x: 3, y: 6.2 },
  { x: 4, y: 7.8 }, { x: 5, y: 10.1 }
];

let w = 0, b = 0;          // parameters to learn
const lr = 0.01;           // learning rate
const epochs = 1000;

for (let epoch = 0; epoch < epochs; epoch++) {
  let gradW = 0, gradB = 0;

  for (const { x, y } of data) {
    const yHat = w * x + b;          // prediction
    const error = yHat - y;          // residual
    gradW += (2 / data.length) * error * x;  // dLoss/dw
    gradB += (2 / data.length) * error;      // dLoss/db
  }

  w -= lr * gradW;  // step opposite to gradient
  b -= lr * gradB;

  if (epoch % 200 === 0) {
    const mse = data.reduce((s, { x, y }) => {
      const e = (w * x + b) - y;
      return s + e * e;
    }, 0) / data.length;
    console.log(`Epoch ${epoch}: w=${w.toFixed(3)}, b=${b.toFixed(3)}, MSE=${mse.toFixed(4)}`);
  }
}

console.log(`\nLearned: y ≈ ${w.toFixed(2)}x + ${b.toFixed(2)}`);
// Expected: close to y = 2x + 0  (true relationship in noisy data)

// ── Train/test split utility ────────────────────────────────────
function trainTestSplit(dataset, testRatio = 0.2) {
  const shuffled = [...dataset].sort(() => Math.random() - 0.5);
  const testSize = Math.floor(dataset.length * testRatio);
  return {
    train: shuffled.slice(testSize),
    test:  shuffled.slice(0, testSize)
  };
}

const { train, test } = trainTestSplit(data, 0.2);
console.log(`Train: ${train.length}, Test: ${test.length}`);
// Train: 4, Test: 1  (80/20 split on 5 examples)

